dashboard.definition:
{
  "title": "DC Networking Operations",
  "description": "Lab observations \u00b7 Five products, one investigation. Missing data is unknown.",
  "inputs": {
    "input_time": {
      "options": {
        "defaultValue": "-24h@h,now,auto",
        "showAdvanced": true,
        "selections": [
          {
            "value": "-4h,now,auto",
            "label": "4h"
          },
          {
            "value": "-24h@h,now,auto",
            "label": "24h"
          },
          {
            "value": "-48h,now,auto",
            "label": "48h"
          },
          {
            "value": "-7d@d,now,auto",
            "label": "7d"
          },
          {
            "value": "-30d@d,now,auto",
            "label": "30d"
          }
        ],
        "token": "time_tok"
      },
      "title": "Time range",
      "type": "input.simpleTimePicker"
    }
  },
  "dataSources": {
    "ds_attention_history": {
      "type": "ds.searchbase",
      "name": "Observed active faults and anomalies",
      "options": {
        "ref": "dc_workspace_attention_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_attention_products": {
      "type": "ds.searchbase",
      "name": "Reported items to review by product",
      "options": {
        "ref": "dc_workspace_attention_products",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_coverage_age": {
      "type": "ds.searchbase",
      "name": "How old is each product\u2019s latest observation?",
      "options": {
        "ref": "dc_workspace_coverage_age",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_inventory_products": {
      "type": "ds.searchbase",
      "name": "Shared inventory: products reporting each switch",
      "options": {
        "ref": "dc_workspace_inventory_products",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_nd_active_history": {
      "type": "ds.searchbase",
      "name": "Nexus Dashboard active-anomaly history",
      "options": {
        "ref": "dc_workspace_nd_active_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_nd_reachability_history": {
      "type": "ds.searchbase",
      "name": "Reported fabric reachability",
      "options": {
        "ref": "dc_workspace_nd_reachability_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_aci_tenant_health_history": {
      "type": "ds.searchbase",
      "name": "ACI observed tenant health",
      "options": {
        "ref": "dc_workspace_aci_tenant_health_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_aci_fault_history": {
      "type": "ds.searchbase",
      "name": "ACI active-fault history",
      "options": {
        "ref": "dc_workspace_aci_fault_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_nexus_cpu_history": {
      "type": "ds.searchbase",
      "name": "Nexus 9000 mean CPU busy",
      "options": {
        "ref": "dc_workspace_nexus_cpu_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_nexus_temperature_history": {
      "type": "ds.searchbase",
      "name": "Nexus 9000 peak reported temperature (Celsius)",
      "options": {
        "ref": "dc_workspace_nexus_temperature_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_san_health_history": {
      "type": "ds.searchbase",
      "name": "MDS observed switch health",
      "options": {
        "ref": "dc_workspace_san_health_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_san_wait_history": {
      "type": "ds.searchbase",
      "name": "SAN highest reported transmit wait",
      "options": {
        "ref": "dc_workspace_san_wait_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_hf_nodes_history": {
      "type": "ds.searchbase",
      "name": "Hyperfabric observed nodes",
      "options": {
        "ref": "dc_workspace_hf_nodes_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    },
    "ds_hf_ports_history": {
      "type": "ds.searchbase",
      "name": "Hyperfabric observed ports",
      "options": {
        "ref": "dc_workspace_hf_ports_history",
        "ownerApp": "splunk-cisco-dashboards",
        "queryParameters": {
          "earliest": "$time_tok.earliest$",
          "latest": "$time_tok.latest$",
          "span": "$time_tok.span$"
        }
      }
    }
  },
  "visualizations": {
    "header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# DC Networking Operations\nLab observations \u00b7 Start with attention, confirm coverage, then follow product evidence.\n\nThe configured DC index macro and selected time window define this overview. Administrative enablement is not availability. Blank measurements are unknown. Shared timing does not prove cause.",
        "backgroundColor": "#1c2738",
        "fontColor": "#ecf0f5"
      }
    },
    "viz_attention_history": {
      "type": "splunk.area",
      "title": "Observed active faults and anomalies",
      "description": "Observed active faults and anomalies",
      "dataSources": {
        "primary": "ds_attention_history"
      },
      "options": {
        "backgroundColor": "#131a23",
        "seriesColors": [
          "#649ef5",
          "#4cbf7f"
        ],
        "legendDisplay": "off",
        "yAxisTitleText": "Observed entities"
      }
    },
    "detail_attention_history": {
      "type": "splunk.cisco_drilldown_action",
      "options": {
        "label": "Investigate Observed active faults and anomalies"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/drilldown?origin=attention_history&target=dc_workspace_attention,dc_workspace_nd_anomalies,dc_workspace_aci_faults,dc_workspace_events"
          }
        }
      ]
    },
    "viz_attention_products": {
      "type": "splunk.bar",
      "title": "Reported items to review by product",
      "description": "Reported items to review by product",
      "dataSources": {
        "primary": "ds_attention_products"
      },
      "options": {
        "backgroundColor": "#131a23",
        "seriesColors": [
          "#649ef5",
          "#4cbf7f"
        ],
        "legendDisplay": "off",
        "yAxisTitleText": "Observed entities"
      }
    },
    "detail_attention_products": {
      "type": "splunk.cisco_drilldown_action",
      "options": {
        "label": "Investigate Reported items to review by product"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/drilldown?origin=attention_products&target=dc_workspace_attention,dc_workspace_events"
          }
        }
      ]
    },
    "viz_coverage_age": {
      "type": "splunk.bar",
      "title": "How old is each product\u2019s latest observation?",
      "description": "How old is each product\u2019s latest observation?",
      "dataSources": {
        "primary": "ds_coverage_age"
      },
      "options": {
        "backgroundColor": "#131a23",
        "seriesColors": [
          "#649ef5",
          "#4cbf7f"
        ],
        "legendDisplay": "off",
        "yAxisTitleText": "min"
      }
    },
    "detail_coverage_age": {
